"""Local two-phase evaluation; only generation imports the submitted Python."""
import contextlib, hashlib, importlib.util, json, pathlib, random, signal, sys, time
BASE = pathlib.Path(__file__).resolve().parent
def digest(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def export(candidate, output):
    sys.path.insert(0, str(candidate.parent))
    spec = importlib.util.spec_from_file_location('candidate_submission', candidate)
    module = importlib.util.module_from_spec(spec); spec.loader.exec_module(module)
    kb = module.KernelBuilder(); kb.build_kernel(10, 2047, 256, 16)
    # Keep bundle positions: jumps address the original instruction stream.
    program = [{k:v for k,v in bundle.items() if k != 'debug'} for bundle in kb.instrs]
    output.write_text(json.dumps(program, separators=(',', ':')))
def verify(program_path, output):
    sys.path.insert(0, str(BASE/'oracle/tests'))
    import frozen_problem as f
    p = json.loads(program_path.read_text()); assert isinstance(p,list) and len(p)<=2000000
    scalar = lambda a: type(a) is int and 0 <= a < 1536
    vector = lambda a: type(a) is int and 0 <= a <= 1528
    ops = {'+','-','*','//','cdiv','^','&','|','<<','>>','%','<','=='}
    for pc,bundle in enumerate(p):
        assert type(bundle) is dict
        for engine,slots in bundle.items():
            assert engine in {'alu','valu','load','store','flow'} and type(slots) is list
            assert len(slots)<=f.SLOT_LIMITS[engine]
            for slot in slots:
                assert type(slot) is list and slot and type(slot[0]) is str
                op,*a=slot; assert all(type(x) is int for x in a)
                if engine=='alu': assert op in ops and len(a)==3 and all(map(scalar,a))
                elif engine=='valu':
                    if op=='vbroadcast': assert len(a)==2 and vector(a[0]) and scalar(a[1])
                    else: assert op in ops|{'multiply_add'} and len(a)==(4 if op=='multiply_add' else 3) and all(map(vector,a))
                elif engine=='load':
                    if op=='const': assert len(a)==2 and scalar(a[0])
                    elif op=='load': assert len(a)==2 and all(map(scalar,a))
                    elif op=='vload': assert len(a)==2 and vector(a[0]) and scalar(a[1])
                    elif op=='load_offset': assert len(a)==3 and 0<=a[2]<8 and scalar(a[0]+a[2]) and scalar(a[1]+a[2])
                    else: raise AssertionError(('load opcode',op))
                elif engine=='store': assert op in {'store','vstore'} and len(a)==2 and scalar(a[0]) and (vector(a[1]) if op=='vstore' else scalar(a[1]))
                elif op in {'halt','pause'}: assert not a
                elif op=='select': assert len(a)==4 and all(map(scalar,a))
                elif op=='vselect': assert len(a)==4 and all(map(vector,a))
                elif op=='add_imm': assert len(a)==3 and all(map(scalar,a[:2]))
                elif op in {'coreid','trace_write','jump_indirect'}: assert len(a)==1 and scalar(a[0])
                elif op=='jump': assert len(a)==1 and 0<=a[0]<=len(p)
                elif op in {'cond_jump','cond_jump_rel'}: assert len(a)==2 and scalar(a[0]) and 0<=(a[1] if op=='cond_jump' else pc+1+a[1])<=len(p)
                else: raise AssertionError(('flow opcode',op))
    seeds=json.loads((BASE/'host/heldout-seeds.json').read_text()); rows=[]
    # This process never imports candidate_submission or the generated workspace.
    for seed in seeds:
        random.seed(seed); forest=f.Tree.generate(10); inp=f.Input.generate(forest,256,16); mem=f.build_mem_image(forest,inp)
        machine=f.Machine(mem,p,f.DebugInfo({}),n_cores=1); machine.enable_pause=False; machine.enable_debug=False
        machine.run()
        for expected in f.reference_kernel2(mem): pass
        start=expected[6]; assert machine.mem[start:start+256]==expected[start:start+256], ('incorrect values',seed)
        rows.append({'seed':seed,'cycles':machine.cycle})
    output.write_text(json.dumps({'correct':True,'worst_cycles':max(r['cycles'] for r in rows),'runs':rows,'program_sha256':digest(program_path),'program_bundles':len(p)},indent=2))
if __name__=='__main__':
    signal.alarm(180)
    mode,candidate,output=sys.argv[1:]; started=time.monotonic()
    (export if mode=='export' else verify)(pathlib.Path(candidate).resolve(),pathlib.Path(output).resolve())
    print(json.dumps({'mode':mode,'wall_seconds':time.monotonic()-started}))
